content:
{
  "code": ":root {
  --color-bg: #ffffff;
  --color-surface: #f5f5f7;
  --color-border: #e5e5ea;
  --color-text-primary: #1d1d1f;
  --color-text-secondary: #86868b;
  --color-accent: #007aff;
  --color-checkbox-bg: #ffffff;
  --color-checkbox-border: #d2d2d7;
  --color-handle-bg: transparent;

  --font-stack-korean: 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
  --font-stack-latin: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;

  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-pill: 999px;

  --type-body: 17px;
  --type-label: 15px;
  --type-small: 13px;

  --line-height-body: 1.5;
  --line-height-tight: 1.2;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--color-bg);
  color: var(--color-text-primary);
  font-family: var(--font-stack-korean), var(--font-stack-latin);
  font-size: var(--type-body);
  line-height: var(--line-height-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app-container {
  width: 100%;
  max-width: 430px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  box-sizing: border-box;
}

.page-header {
  padding-top: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
  text-align: center;
}

#page-title {
  margin: 0;
  font-size: 28px;
  font-weight: 700;
  line-height: var(--line-height-tight);
  letter-spacing: -0.02em;
  color: var(--color-text-primary);
}

.destination-pills {
  display: flex;
  justify-content: center;
  gap: var(--spacing-sm);
  margin-bottom: var(--spacing-xl);
}

.pill {
  padding: 8px 16px;
  border-radius: var(--radius-pill);
  border: none;
  background-color: var(--color-surface);
  color: var(--color-text-secondary);
  font-family: inherit;
  font-size: var(--type-label);
  font-weight: 500;
  cursor: default;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.pill.active {
  background-color: var(--color-text-primary);
  color: var(--color-bg);
}

#itinerary-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
  flex: 1;
  padding-bottom: var(--spacing-lg);
}

.day-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.day-header {
  display: flex;
  align-items: baseline;
  gap: var(--spacing-xs);
  padding-left: var(--spacing-xs);
}

.day-label {
  font-size: 20px;
  font-weight: 600;
  color: var(--color-text-primary);
  line-height: var(--line-height-tight);
}

.day-date {
  font-size: 15px;
  font-weight: 400;
  color: var(--color-text-secondary);
  line-height: var(--line-height-tight);
}

.places-list {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.place-row {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  padding: var(--spacing-sm);
  background-color: var(--color-surface);
  border-radius: var(--radius-md);
}

.place-row input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin: 0;
  cursor: default;
  flex-shrink: 0;
}

.place-content-wrapper {
  display: flex;
  align-items: center;
  gap: var(--spacing-sm);
  flex: 1;
  min-width: 0;
}

.place-image {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  flex-shrink: 0;
  background-color: #e5e5ea;
}

.place-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.place-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  overflow: hidden;
}

.place-name {
  font-size: var(--type-label);
  font-weight: 500;
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: var(--line-height-tight);
}

.place-meta {
  display: flex;
  align-items: center;
  gap: var(--spacing-xs);
  font-size: var(--type-small);
  color: var(--color-text-secondary);
  line-height: var(--line-height-tight);
}

.place-region::after {
  content: '•';
  margin-left: var(--spacing-xs);
  opacity: 0.5;
}

.reorder-handle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  padding: 0;
  cursor: grab;
  color: var(--color-text-secondary);
  flex-shrink: 0;
}

.reorder-handle img {
  width: 16px;
  height: 16px;
  pointer-events: none;
}

.action-footer {
  padding-top: var(--spacing-md);
  padding-bottom: env(safe-area-inset-bottom, 0);
}

.btn-primary {
  width: 100%;
  padding: 16px;
  border: none;
  border-radius: var(--radius-md);
  background-color: var(--color-accent);
  color: #ffffff;
  font-family: inherit;
  font-size: var(--type-label);
  font-weight: 600;
  cursor: default;
  opacity: 0.5;
  transition: opacity 0.2s ease;
}

@media (max-width: 390px) {
  .app-container {
    padding-left: var(--spacing-sm);
    padding-right: var(--spacing-sm);
  }

  .place-content-wrapper {
    gap: var(--spacing-xs);
  }

  .place-image {
    width: 40px;
    height: 40px;
  }

  .place-name {
    font-size: 15px;
  }
}

@media (max-width: 320px) {
  #page-title {
    font-size: 24px;
  }

  .day-label {
    font-size: 18px;
  }

  .place-meta {
    flex-direction: column;
    align-items: flex-start;
    gap: 0;
  }

  .place-region::after {
    content: none;
  }
}"
}
